"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { 
  LogOut, 
  Bell, 
  UtensilsCrossed,
  Receipt,
  Clock
} from "lucide-react";

// Dummy data for tables
const DUMMY_TABLES = Array.from({ length: 20 }, (_, i) => ({
  id: i + 1,
  tableNumber: i + 1,
  status: "free", // free, occupied, bill_pending
  currentBill: 0,
  guests: 0,
  orderId: null,
  seatedAt: null
}));

export default function StaffHome() {
  const router = useRouter();
  const [staff, setStaff] = useState({ name: "Rohan Kumar" });
  const [tables, setTables] = useState(DUMMY_TABLES);
  const [stats, setStats] = useState({
    free: 20,
    occupied: 0,
    billPending: 0,
    totalOrders: 0
  });

  useEffect(() => {
    // Check auth
    const token = localStorage.getItem("staffToken");
    if (!token) {
      router.push("/business/staff/login");
      return;
    }

    // Update stats
    updateStats();
  }, [tables]);

  const updateStats = () => {
    const free = tables.filter(t => t.status === "free").length;
    const occupied = tables.filter(t => t.status === "occupied").length;
    const billPending = tables.filter(t => t.status === "bill_pending").length;
    setStats({ free, occupied, billPending, totalOrders: occupied + billPending });
  };

  const handleLogout = () => {
    localStorage.removeItem("staffToken");
    localStorage.removeItem("staffUser");
    router.push("/business/staff/login");
  };

  const getTableColor = (status) => {
    switch (status) {
      case "free": return "bg-gradient-to-br from-green-400 to-green-500 text-white";
      case "occupied": return "bg-gradient-to-br from-orange-400 to-orange-500 text-white";
      case "bill_pending": return "bg-gradient-to-br from-blue-400 to-blue-500 text-white";
      default: return "bg-gray-300 text-gray-700";
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case "free": return "Free";
      case "occupied": return "Occupied";
      case "bill_pending": return "Bill Pending";
      default: return "Unknown";
    }
  };

  const handleTableClick = (table) => {
    if (table.status === "free") {
      router.push(`/business/staff/table/${table.id}/order`);
    } else {
      router.push(`/business/staff/table/${table.id}/manage`);
    }
  };

  const currentHour = new Date().getHours();
  const shift = currentHour < 16 ? "Morning" : currentHour < 20 ? "Evening" : "Night";

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-orange-50 to-gray-50">
      {/* HEADER */}
      <header className="bg-white shadow-lg sticky top-0 z-50 border-b-4 border-orange-500">
        <div className="container mx-auto px-6 py-5">
          <div className="flex items-center justify-between">
            {/* Left: Greeting */}
            <div>
              <h1 className="text-3xl font-bold bg-gradient-to-r from-orange-600 to-red-600 bg-clip-text text-transparent">
                Hello, {staff?.name} 👋
              </h1>
              <p className="text-sm text-gray-600 mt-1 flex items-center gap-2">
                <Clock className="w-4 h-4" />
                Shift: {shift} | {new Date().toLocaleTimeString('en-US', { 
                  hour: '2-digit', 
                  minute: '2-digit' 
                })}
              </p>
            </div>

            {/* Right: Actions */}
            <div className="flex items-center gap-4">
              <button 
                onClick={() => router.push("/business/staff/running-orders")}
                className="relative p-3 hover:bg-orange-50 rounded-xl transition-colors group"
              >
                <Receipt className="w-6 h-6 text-gray-700 group-hover:text-orange-600" />
                {stats.totalOrders > 0 && (
                  <span className="absolute -top-1 -right-1 w-6 h-6 bg-red-500 text-white text-xs font-bold rounded-full flex items-center justify-center">
                    {stats.totalOrders}
                  </span>
                )}
              </button>
              <button className="relative p-3 hover:bg-orange-50 rounded-xl transition-colors group">
                <Bell className="w-6 h-6 text-gray-700 group-hover:text-orange-600" />
                <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full"></span>
              </button>
              <button
                onClick={handleLogout}
                className="flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-red-500 to-red-600 hover:from-red-600 hover:to-red-700 text-white rounded-xl transition-all font-semibold shadow-lg hover:shadow-xl"
              >
                <LogOut className="w-4 h-4" />
                Logout
              </button>
            </div>
          </div>
        </div>
      </header>

      <div className="container mx-auto px-6 py-8">
        {/* STATS OVERVIEW */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white p-6 rounded-2xl shadow-lg border-l-4 border-green-500 hover:shadow-xl transition-shadow">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold uppercase tracking-wide">Tables Free</p>
                <p className="text-4xl font-bold text-gray-800 mt-2">{stats.free}</p>
              </div>
              <div className="w-16 h-16 bg-green-100 rounded-2xl flex items-center justify-center">
                <UtensilsCrossed className="w-8 h-8 text-green-600" />
              </div>
            </div>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-lg border-l-4 border-orange-500 hover:shadow-xl transition-shadow">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold uppercase tracking-wide">Occupied</p>
                <p className="text-4xl font-bold text-gray-800 mt-2">{stats.occupied}</p>
              </div>
              <div className="w-16 h-16 bg-orange-100 rounded-2xl flex items-center justify-center">
                <UtensilsCrossed className="w-8 h-8 text-orange-600" />
              </div>
            </div>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-lg border-l-4 border-blue-500 hover:shadow-xl transition-shadow">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold uppercase tracking-wide">Bill Pending</p>
                <p className="text-4xl font-bold text-gray-800 mt-2">{stats.billPending}</p>
              </div>
              <div className="w-16 h-16 bg-blue-100 rounded-2xl flex items-center justify-center">
                <Receipt className="w-8 h-8 text-blue-600" />
              </div>
            </div>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-lg border-l-4 border-purple-500 hover:shadow-xl transition-shadow">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold uppercase tracking-wide">Active Orders</p>
                <p className="text-4xl font-bold text-gray-800 mt-2">{stats.totalOrders}</p>
              </div>
              <div className="w-16 h-16 bg-purple-100 rounded-2xl flex items-center justify-center">
                <Receipt className="w-8 h-8 text-purple-600" />
              </div>
            </div>
          </div>
        </div>

        {/* TABLE GRID */}
        <div className="bg-white p-8 rounded-3xl shadow-2xl">
          <div className="flex items-center justify-between mb-8">
            <h2 className="text-3xl font-bold text-gray-800">Table Overview</h2>
            <div className="flex gap-4 text-sm font-medium">
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 bg-gradient-to-br from-green-400 to-green-500 rounded"></div>
                <span>Free</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 bg-gradient-to-br from-orange-400 to-orange-500 rounded"></div>
                <span>Occupied</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 bg-gradient-to-br from-blue-400 to-blue-500 rounded"></div>
                <span>Bill Pending</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-5">
            {tables.map((table) => (
              <button
                key={table.id}
                onClick={() => handleTableClick(table)}
                className={`${getTableColor(table.status)} rounded-2xl p-6 shadow-lg hover:shadow-2xl transition-all transform hover:scale-105 active:scale-95`}
              >
                <div className="text-center">
                  <p className="text-5xl font-bold mb-2">{table.tableNumber}</p>
                  <div className="bg-white bg-opacity-30 backdrop-blur-sm rounded-lg py-2 px-3 mb-3">
                    <p className="text-sm font-bold">{getStatusText(table.status)}</p>
                  </div>
                  {table.currentBill > 0 && (
                    <p className="text-sm font-semibold">₹{table.currentBill}</p>
                  )}
                  {table.guests > 0 && (
                    <p className="text-xs mt-1 opacity-90">{table.guests} guests</p>
                  )}
                </div>
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}